function validate([date]) {
  if (typeof date !== 'string') return 'date must be a string.';
  const match = /^(\d{1,2})(st|nd|rd|th) ([A-Z][a-z]{2}) (\d{4})$/.exec(date);
  if (!match) return 'date must look like "20th Oct 2052".';
  const day = Number(match[1]);
  const names = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const month = names.indexOf(match[3]);
  const year = Number(match[4]);
  if (month < 0) return 'The month must be a three-letter abbreviation such as Jan or Oct.';
  if (year < 1900 || year > 2100) return 'The year must be between 1900 and 2100.';
  if (match[1][0] === '0' || day < 1 || day > 31) return 'The day must be between 1st and 31st, without a leading zero.';
  const suffix = day % 10 === 1 && day !== 11 ? 'st' : day % 10 === 2 && day !== 12 ? 'nd' : day % 10 === 3 && day !== 13 ? 'rd' : 'th';
  if (match[2] !== suffix) return `Day ${day} is written ${day}${suffix}.`;
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const lengths = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > lengths[month]) return `${match[3]} ${year} has only ${lengths[month]} days.`;
  return null;
}

