function reformatDate(date) {
  const table = { Jan: "01", Feb: "02", Mar: "03", Apr: "04", May: "05", Jun: "06", Jul: "07", Aug: "08", Sep: "09", Oct: "10", Nov: "11", Dec: "12" };
  let digits = "";
  let i = 0;
  while (date[i] >= "0" && date[i] <= "9") digits += date[i++];
  const rest = date.slice(date.indexOf(" ") + 1);
  const mon = rest.slice(0, 3);
  const yr = rest.slice(4);
  return `${yr}-${table[mon]}-${digits.length === 1 ? "0" + digits : digits}`;
}

