function generate(rand, size) {
  const names = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const ordinal = d => {
    if (d % 10 === 1 && d !== 11) return d + "st";
    if (d % 10 === 2 && d !== 12) return d + "nd";
    if (d % 10 === 3 && d !== 13) return d + "rd";
    return d + "th";
  };
  const year = 1900 + Math.floor(rand() * 201);
  const month = Math.floor(rand() * 12);
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const lengths = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  let day;
  const pick = rand();
  if (size === 'small' && pick < 0.2) day = 1;
  else if (size === 'small' && pick < 0.4) day = lengths[month];
  else day = 1 + Math.floor(rand() * lengths[month]);
  return [`${ordinal(day)} ${names[month]} ${year}`];
}
